from taf.gnb.oam.coam.cu.services.internal.pm.http_client_v2 import PMv2HttpClient
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh()
class PMv2:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = PMv2HttpClient(base_url=con_details.base_url, connection_alias=con_details.alias)

    def get_counter(self, dimension_dist_name, counter_id, timeout=30, start_time_lower_limit=None, start_time_upper_limit=None):
        limits = {
            'start_time_lower_limit': start_time_lower_limit,
            'start_time_upper_limit': start_time_upper_limit
        }
        kwargs = {k: v for k, v in limits.items() if v is not None}

        return self.local_client.get_counter(counter=[f"{counter_id}:{dimension_dist_name}"], timeout=timeout, **kwargs)

    def get_counter_objects(self, counter_id, timeout=30):
        return self.local_client.get_counter_objects(counter_id=counter_id, timeout=timeout)

    def get_measurements(self):
        return self.local_client.get_measurements()

    def get_counter_info(self, counter_id):
        return self.local_client.get_counter_info(counter_id=counter_id)
